import{z as s,x as l,o as t,c as d,q as o,j as r,D as E,d as e,s as B,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"点时数据库的构建","description":"","frontmatter":{"title":"点时数据库的构建","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-pointintime-db.md","filePath":"quant/de-pointintime-db.md","lastUpdated":1791063341000}'),m={name:"quant/de-pointintime-db.md"};function p(u,a,f,D,h,C){const i=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="点时数据库的构建" tabindex="-1">点时数据库的构建 <a class="header-anchor" href="#点时数据库的构建" aria-label="Permalink to &quot;点时数据库的构建&quot;">​</a></h1><div class="epigraph"><p>宏观经济学家花了一个十年才建成实时数据集，因为他们发现政策评估里的「当时知道」无法靠回忆重建；投研平台的教训相同，只是代价以假 alpha 计。</p><footer>—— 据 Croushore and Stark, A Real-Time Data Set for Macroeconomists, Journal of Econometrics, 2001 整理</footer></div><p><a href="/quant/de-data-versioning">上一课</a>让每个数据集有了不可变的版本链；本课把这些版本收成一个可查询的库：给定任意决策日 \\(t\\) 与任意字段，返回「截至 \\(t\\) 已公开的最新值」。为什么与怎么的分工已经立好——<a href="/quant/point-in-time">时点基本面</a>与 <a href="/quant/pit-fundamentals">Point-in-time 基本面</a>讲清了 latest-available 为何泄漏，本课讲库怎么建：模式、摄取、查询与校验四层。回测对齐的做法在<a href="/quant/pit-alignment">点-in-time 基本面对齐</a>有基础版，本课把它变成平台函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PIT 库的核心是一张双时间轴表。每行 \\((entity, field, value)\\) 带两枚时间戳：有效时间（这行关于哪个时期，如财季结束日）与事务时间（这行何时进入知识集，如公告日、更正日落库日）。<span class="marginnote">术语翻译：有效时间是「这条数据<strong>关于</strong>哪段时间」，比如 2025 年一季报写的是 3 月 31 日那个季度；事务时间是「这条数据<strong>什么时候才有人能看到</strong>」，比如 4 月 28 日公告。回测在 4 月 10 日只能用事务时间不超过 4 月 10 日的行——只用第一枚时间戳对齐，就是最经典的泄漏。</span>教科书里叫有效时间与事务时间，宏观传统叫 vintage，投研叫可得日——三套名字一件事。难点都在边缘：更正是覆盖还是并列（收入重述通常并列保留旧值，错误更正通常覆盖）；公告在非交易时段时，事务时间要归到下一个可交易的决策时点，否则回测会「在公告当晚收盘前」交易<span class="marginnote">直觉类比：把事务时间归到下一个可交易时点，就像快递只能在工作日签收——周五晚上送达的包裹，你的「签收动作」最早也是周一开盘。若允许回测在周五夜里下单，等于用了现实中不存在的交易时刻，泄漏就从这里进来。</span>；行业分类、股本、指数成分都是字段，同样要进这张表——只把报表 PIT 化而成分用今天的列表，等于修了一条腿的泄漏，见<a href="/quant/survivorship-bias">幸存者偏差</a>。</p><p><span class="marginnote">Croushore 与 Stark 建实时数据集的动机与本课同构：GDP 初值与终值系统性不同，用终值评估「当时的美联储」是让政策制定者预知未来。基本面的初值与终值同理，见<a href="/quant/fundamentals-restatements">基本面数据与重述</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四层落地。<strong>摄取层</strong>：供应商快照原样落盘为不可变批次，不做任何合并——这是事务时间的唯一可信来源，任何「聪明的合并」都等于销毁证据；<span class="marginnote">常见误区：初学者容易以为「落盘前先把快照合并干净」是工程好习惯。恰恰相反：合并会抹掉「哪条值是哪天进的库」，事务时间从此无从考证，更正是覆盖还是并列也不再可查。证据要先把原始批次冻起来，清洗和合并放到下游的查询层去做。</span>映射到统一实体键（永久号而非代码），口径与<a href="/quant/alt-panel-construction">面板构造</a>一致。<strong>模式层</strong>：上述双时间轴表加字段级元数据（单位、口径、来源）；供应商改字段定义等同新字段，沿用<a href="/quant/data-acquisition-audit">数据获取与审计</a>的重审义务。<strong>查询层</strong>：全平台只有一个 as-of 函数——研究、生产、监控共用同一实现，把 \\(\\mathrm{published\\_at}\\le t\\) 的最大有效行收成一次扫描；不同的调用方写自己的包装，不许写自己的实现。<strong>校验层</strong>：每期抽若干实体，把 as-of 结果与留存的 vintage 快照对账；没有快照的字段标记降级。</p>',8)),(t(),r(A,null,{default:E(()=>[B(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%BF%AB%E7%85%A7%E6%89%B9%E6%AC%A1%EF%BC%9A%E4%B8%8D%E5%8F%AF%E5%8F%98%22%5D%20--%3E%20KEY%5B%22%E5%AE%9E%E4%BD%93%E9%94%AE%E5%BD%92%E4%B8%80%EF%BC%9A%E6%B0%B8%E4%B9%85%E5%8F%B7%22%5D%0A%20%20KEY%20--%3E%20BITE%5B%22%E5%8F%8C%E6%97%B6%E9%97%B4%E8%BD%B4%E8%A1%A8%EF%BC%9A%E6%9C%89%E6%95%88%E6%97%B6%E9%97%B4%20%2B%20%E4%BA%8B%E5%8A%A1%E6%97%B6%E9%97%B4%22%5D%0A%20%20BITE%20--%3E%20API%5B%22%E5%94%AF%E4%B8%80%20as-of%20%E6%9F%A5%E8%AF%A2%E5%87%BD%E6%95%B0%22%5D%0A%20%20API%20--%3E%20RES%5B%22%E7%A0%94%E7%A9%B6%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20API%20--%3E%20PROD%5B%22%E7%94%9F%E4%BA%A7%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20API%20--%3E%20MON%5B%22%E6%95%B0%E6%8D%AE%E7%9B%91%E6%8E%A7%22%5D%0A%20%20VINT%5B%22vintage%20%E5%BF%AB%E7%85%A7%E5%AD%98%E6%A1%A3%22%5D%20--%3E%20CHK%5B%22%E5%AF%B9%E8%B4%A6%E6%A0%A1%E9%AA%8C%EF%BC%9A%E9%99%8D%E7%BA%A7%E6%A0%87%E8%AE%B0%22%5D%0A%20%20CHK%20--%3E%20BITE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"单点实现之所以是关键，在于泄漏治理与软件缺陷治理同构：逻辑散在多处时，修一处漏一处，你永远不知道生产在用什么知识集。唯一的 as-of 函数让「平台的时间语义」成为一个可测试的对象——函数升级走回归测试，测试集就是校验层攒下的 vintage 对账用例。双时间轴的另一个收益是可逆：从今天往回看是「最新值」，从事后任意一天往回看是「当时值」，两个视角由同一份数据支持，因为事务时间从未被抹去。这正是上一课版本化在字段粒度的延续：版本链管数据集，双时间轴管行，快照对账管整体。于是「同一因子在 A 库显著、B 库不显著」这类争论有了第三个出口——两家库的事务时间政策不同，可以把差值定位到具体字段的具体更正，而不是停在「数据不一样」。",-1)),(t(),r(A,null,{default:E(()=>[B(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E8%A1%8C%E4%B8%80%3A%20Q1%20%E5%87%80%E5%88%A9%E5%88%9D%E5%80%BC%2C%20%E4%BA%8B%E5%8A%A1%E6%97%B6%E9%97%B4%20%3D%204%2F28%22%5D%20--%3E%20Q1%5B%22as-of(5%2F1)%20%E8%BF%94%E5%9B%9E%3A%20%E5%88%9D%E5%80%BC%22%5D%0A%20%20R2%5B%22%E8%A1%8C%E4%BA%8C%3A%20%E5%90%8C%E4%B8%80%20Q1%20%E5%87%80%E5%88%A9%E9%87%8D%E8%BF%B0%2C%20%E4%BA%8B%E5%8A%A1%E6%97%B6%E9%97%B4%20%3D%208%2F15%2C%20%E6%97%A7%E5%80%BC%E5%B9%B6%E5%88%97%E4%BF%9D%E7%95%99%22%5D%20--%3E%20Q2%5B%22as-of(5%2F1)%20%E4%BB%8D%E8%BF%94%E5%9B%9E%3A%20%E5%88%9D%E5%80%BC%22%5D%0A%20%20R2%20--%3E%20Q3%5B%22as-of(9%2F1)%20%E8%BF%94%E5%9B%9E%3A%20%E9%87%8D%E8%BF%B0%E5%80%BC%22%5D%0A%20%20Q1%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E8%A1%A8%2C%20%E4%B8%8D%E5%90%8C%E5%86%B3%E7%AD%96%E6%97%A5%E7%9C%8B%E5%88%B0%E4%B8%8D%E5%90%8C%E7%9F%A5%E8%AF%86%E9%9B%86%22%5D%0A%20%20Q2%20--%3E%20SAME%0A%20%20Q3%20--%3E%20SAME%0A%20%20SAME%20--%3E%20NOLEAK%5B%22%E5%9B%9E%E6%B5%8B%E6%8C%89%E5%90%84%E8%87%AA%20t%20%E6%9F%A5%E8%AF%A2%3A%20%E6%97%A0%E6%9C%AA%E6%9D%A5%E4%BF%A1%E6%81%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PIT 库不解决语义：它保证「当时在场」，不保证字段含义跨年可比（会计准则变更要在字段层另建口径）。覆盖有硬边界：更正链的完整性取决于供应商是否交付历次快照，早期年份常只有初值，降级用法要写进审计报告。性能上，双时间轴表比宽表贵，查询要靠分区与物化视图撑——这是下一课分布式回测架构的题目。最后，文本、舆情类另类数据的转载与修订同样吃事务时间，接<a href="/quant/alt-data-backfill-bias">回填偏差</a>的口径，不在本课展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIT 的核心是双时间轴：有效时间管「关于何时」，事务时间管「何时可知」。</li><li>摄取只落原始快照，合并即销毁证据；归一到永久实体键。</li><li>全平台唯一 as-of 函数，研究、生产、监控共用，升级走回归测试。</li><li>行业、股本、成分同 as-of，只修报表是单腿泄漏。</li><li>vintage 对账决定字段可用等级，没有快照就显式降级。</li><li>出处：Croushore and Stark, <em>A Real-Time Data Set for Macroeconomists</em>, <em>Journal of Econometrics</em>, 2001；站内<a href="/quant/point-in-time">时点基本面</a>与<a href="/quant/pit-alignment">点-in-time 基本面对齐</a>各课。</li></ul>',4))])}const g=s(m,[["render",p]]);export{F as __pageData,g as default};
